
--------------------------------------- SQL PROJECT---------------------------------------------------------------

create database crop_yield_project;
use crop_yield_project;
create table crop_yield(id int auto_increment primary key,crop varchar(50),year int,season varchar(20),state varchar(50), area float,production float,fertilizer float,pesticide float,yield_value float); 
create table soil_data(id int auto_increment primary key,state varchar(50),Nitrogen float,Phosphorus float,Potassium float,Soil_pH FLOAT);
create table weather_data (id int auto_increment primary key,state varchar(50),year int,avg_temp_c float,total_rainfall_mm float,avg_humidity_percent float);

